example_code:
$ aws s3api put-bucket-lifecycle-configuration \
    --bucket ml-data-lake \
    --lifecycle-configuration file://lifecycle.json

# lifecycle.json
{
  "Rules": [
    {
      "ID": "archive-raw-layer",
      "Filter": {"Prefix": "raw/"},
      "Status": "Enabled",
      "Transitions": [
        {"Days": 30, "StorageClass": "STANDARD_IA"},
        {"Days": 90, "StorageClass": "GLACIER"}
      ],
      "Expiration": {"Days": 365}
    }
  ]
}

$ aws s3api get-bucket-lifecycle-configuration --bucket ml-data-lake
